begin;
do $$
declare admin_uid uuid:=gen_random_uuid();prof_uid uuid:=gen_random_uuid();other_uid uuid:=gen_random_uuid();ta uuid;tb uuid;plan uuid;pro uuid;other_pro uuid;sid uuid;cid uuid;aid uuid;sub_id uuid;x jsonb;denied boolean;key_public text;ep text:='https://fcm.googleapis.com/fcm/send/agenda-fixture-'||gen_random_uuid();today date:=(now() at time zone 'America/Sao_Paulo')::date;
begin
 insert into auth.users(id,email,email_confirmed_at) values(admin_uid,'push-admin@example.invalid',now()),(prof_uid,'push-pro@example.invalid',now()),(other_uid,'push-other@example.invalid',now());
 insert into public.plans(name,amount,months) values('Fixture Push',0,1) returning id into plan;
 insert into public.tenants(name,slug,responsible,email) values('Push Fixture A','push-fixture-'||substr(admin_uid::text,1,8),'Teste','push-admin@example.invalid') returning id into ta;
 insert into public.tenants(name,slug,responsible,email) values('Push Fixture B','push-fixture-'||substr(other_uid::text,1,8),'Teste','push-other@example.invalid') returning id into tb;
 insert into public.licenses(tenant_id,plan_id,starts_on,expires_on) values(ta,plan,today-1,today+30),(tb,plan,today-1,today+30);
 insert into public.professionals(tenant_id,name) values(ta,'Profissional responsável') returning id into pro;
 insert into public.professionals(tenant_id,name) values(ta,'Outro profissional') returning id into other_pro;
 insert into public.memberships(tenant_id,email,user_id,role,professional_id) values(ta,'push-admin@example.invalid',admin_uid,'admin',null),(ta,'push-pro@example.invalid',prof_uid,'professional',pro),(tb,'push-other@example.invalid',other_uid,'admin',null);
 select value into key_public from app_private.secrets where key='push_vapid_public';
 perform set_config('request.jwt.claim.sub',admin_uid::text,true);
 perform public.agenda_push_client('register',jsonb_build_object('tenant_id',ta,'subscription',jsonb_build_object('endpoint',ep,'keys',jsonb_build_object('p256dh',key_public,'auth',repeat('a',22)))));
 x:=public.agenda_push_client('status',jsonb_build_object('tenant_id',ta,'endpoint',ep));if x->>'enabled'<>'true' or x ? 'push_vapid_private' or x ? 'push_dispatch' then raise exception 'FAIL client config privacy';end if;
 denied:=false;begin perform public.agenda_push_client('status',jsonb_build_object('tenant_id',tb));exception when others then denied:=true;end;if not denied then raise exception 'FAIL cross tenant config';end if;
 denied:=false;begin perform public.agenda_push_client('register',jsonb_build_object('tenant_id',ta,'subscription',jsonb_build_object('endpoint','https://127.0.0.1/private','keys',jsonb_build_object('p256dh',key_public,'auth',repeat('a',22)))));exception when others then denied:=true;end;if not denied then raise exception 'FAIL arbitrary endpoint';end if;
 perform set_config('request.jwt.claim.sub',prof_uid::text,true);
 perform public.agenda_push_client('register',jsonb_build_object('tenant_id',ta,'subscription',jsonb_build_object('endpoint',ep||'-pro','keys',jsonb_build_object('p256dh',key_public,'auth',repeat('b',22)))));
 perform set_config('request.jwt.claim.sub',other_uid::text,true);
 perform public.agenda_push_client('register',jsonb_build_object('tenant_id',tb,'subscription',jsonb_build_object('endpoint',ep||'-other','keys',jsonb_build_object('p256dh',key_public,'auth',repeat('c',22)))));
 insert into public.services(tenant_id,name,duration,price) values(ta,'Serviço fixture',30,35) returning id into sid;
 insert into public.customers(tenant_id,name,phone) values(ta,'Cliente fixture','24999999999') returning id into cid;
 insert into public.appointments(tenant_id,professional_id,service_id,customer_id,starts_at,ends_at,price) values(ta,pro,sid,cid,now(),now()+interval '30 minutes',35) returning id into aid;
 if (select count(*) from app_private.push_deliveries where appointment_id=aid)<>2 then raise exception 'FAIL admin and assigned professional delivery';end if;
 insert into public.appointments(tenant_id,professional_id,service_id,customer_id,starts_at,ends_at,price) values(ta,other_pro,sid,cid,now(),now()+interval '30 minutes',35) returning id into aid;
 if (select count(*) from app_private.push_deliveries where appointment_id=aid)<>1 then raise exception 'FAIL other professional isolation';end if;
 insert into public.appointments(tenant_id,professional_id,starts_at,ends_at,status) values(ta,pro,now()+interval '1 hour',now()+interval '2 hours','Bloqueado') returning id into aid;
 if exists(select 1 from app_private.push_deliveries where appointment_id=aid) then raise exception 'FAIL blocked slot notification';end if;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 x:=public.agenda_push_worker('claim','{}');if jsonb_array_length(x)<>3 then raise exception 'FAIL delivery claim';end if;
 if jsonb_array_length(public.agenda_push_worker('claim','{}'))<>0 then raise exception 'FAIL duplicate concurrent lease';end if;
 perform public.agenda_push_worker('finish',jsonb_build_object('id',x->0->>'id','lease',gen_random_uuid(),'state','sent','status',201));
 if exists(select 1 from app_private.push_deliveries where state='sent') then raise exception 'FAIL forged lease accepted';end if;
 perform public.agenda_push_worker('finish',jsonb_build_object('id',x->0->>'id','lease',x->0->>'lease','state','sent','status',201));
 if not exists(select 1 from app_private.push_deliveries where state='sent') then raise exception 'FAIL delivery acknowledgement';end if;
 perform set_config('request.jwt.claims','{}',true);perform set_config('request.jwt.claim.sub',admin_uid::text,true);
 perform public.agenda_push_client('logout','{}');if exists(select 1 from public.push_subscriptions where user_id=admin_uid and active) then raise exception 'FAIL logout does not stop devices';end if;
 perform set_config('request.jwt.claim.sub',prof_uid::text,true);
 perform public.agenda_push_client('unregister',jsonb_build_object('tenant_id',ta,'endpoint',ep||'-pro'));
 if exists(select 1 from public.push_subscriptions where user_id=prof_uid and active) then raise exception 'FAIL opt-out';end if;
 if has_function_privilege('anon','public.agenda_push_client(text,jsonb)','EXECUTE') or has_function_privilege('authenticated','public.agenda_push_worker(text,jsonb)','EXECUTE') or has_table_privilege('authenticated','public.push_subscriptions','SELECT') then raise exception 'FAIL excessive privileges';end if;
end $$;
select 'PASS: opt-in/out, tenant and professional isolation, destination validation, no secrets to client, booking-only trigger, lease concurrency, acknowledgements, logout and grants' as result;
rollback;
